// Filtro currificado para pipelines de datos
const filtrarPor = (propiedad) => (valor) => (array) =>
  array.filter(item => item[propiedad] === valor);

const productos = [
  { nombre: 'Libro JS', categoria: 'tech', precio: 45000 },
  { nombre: 'Novela', categoria: 'literatura', precio: 25000 },
  { nombre: 'Curso React', categoria: 'tech', precio: 80000 },
];

const filtrarCategoria = filtrarPor('categoria');
const soloTech = filtrarCategoria('tech');

console.log(soloTech(productos).map(p => p.nombre));
// ['Libro JS', 'Curso React']

const pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);

// Transformaciones de strings
const trim = s => s.trim();
const lower = s => s.toLowerCase();
const replaceSpaces = (char) => (s) => s.replace(/\s+/g, char);
const truncar = (max) => (s) => s.length > max ? s.slice(0, max) + '...' : s;

// Pipeline para generar slugs
const generarSlug = pipe(
  trim,
  lower,
  replaceSpaces('-'),
  truncar(30)
);

console.log(generarSlug('  JavaScript para Principiantes  '));
// 'javascript-para-principiantes'

console.log(generarSlug('  Introducción a la Programación Funcional en JS  '));
// 'introducción-a-la-programación-f...'

